changeSet.sql:
ALTER TABLE acceptance_transfer_act RENAME COLUMN customer_id to customer_id_old;
ALTER TABLE acceptance_transfer_act ADD COLUMN IF NOT EXISTS customer_id BIGINT;
Update acceptance_transfer_act set customer_id=(select customer.id from customer where customer.customer_id=acceptance_transfer_act.customer_id_old limit 1);
ALTER TABLE acceptance_transfer_act ADD FOREIGN KEY (customer_id) REFERENCES customer;

ALTER TABLE shipment ADD COLUMN IF NOT EXISTS customer_id BIGINT;
update shipment SET customer_id=(SELECT customer.id FROM customer WHERE customer.customer_id=shipment.to_organization_id AND customer.organization_id=shipment.organization_id limit 1);
ALTER TABLE shipment ADD FOREIGN KEY (customer_id) REFERENCES customer;

ALTER TABLE customer ADD COLUMN IF NOT EXISTS tin varchar(14);
ALTER TABLE customer ADD COLUMN IF NOT EXISTS name varchar(255);

UPDATE customer c set tin = (select tin from organization where id = c.customer_id);
UPDATE customer c set name = (select name from organization where id = c.customer_id);

ALTER TABLE customer DROP COLUMN IF EXISTS customer_id;

            ALTER TABLE list_invoice ADD COLUMN IF NOT EXISTS seller_tin varchar(14);
            ALTER TABLE list_invoice ADD COLUMN IF NOT EXISTS seller_name varchar(255);
            ALTER TABLE list_invoice ADD COLUMN IF NOT EXISTS buyer_tin varchar(14);
            ALTER TABLE list_invoice ADD COLUMN IF NOT EXISTS buyer_name varchar(255);

